# -*- coding: utf-8 -*-
"""دفعة متقدمة لكل قسم."""
from biz_tools import F, S, add, CATS, T
OL="function ol(a){return'<ol>'+a.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol>'}"

# ---- المالية
add('npv-irr-calculator','finance','💹','حاسبة NPV وIRR وفترة الاسترداد','قيّم مشروعًا استثماريًا بصافي القيمة الحالية ومعدل العائد الداخلي.',
 [F('i','الاستثمار الأولي','n',200000),F('c','التدفقات السنوية (فاصلة)','text','60000,70000,80000,80000,70000'),F('r','معدل الخصم %','n',10)],
 r'''function compute(v){const C=v.c.split(',').map(Number).filter(x=>!isNaN(x)),r=v.r/100;const npv=(rt)=>C.reduce((a,x,i)=>a+x/Math.pow(1+rt,i+1),-v.i);let lo=-0.9,hi=2,irr=0;for(let k=0;k<100;k++){irr=(lo+hi)/2;npv(irr)>0?lo=irr:hi=irr}let cum=-v.i,pb='لا يسترد';C.forEach((x,i)=>{if(cum<0&&cum+x>=0)pb=(i+(-cum)/x).toFixed(1)+' سنة';cum+=x});return kpis([kpi('NPV',f(npv(r)),npv(r)>0?'good':'bad'),kpi('IRR',f(irr*100,1)+'%',irr>r?'good':'bad'),kpi('فترة الاسترداد',pb),kpi('مؤشر الربحية',f((npv(r)+v.i)/v.i,2))])+rec([npv(r)>0?'المشروع يضيف قيمة بمعدل خصم '+v.r+'%.':'المشروع لا يحقق العائد المطلوب.','اختبر حساسية النتيجة بمعدلات خصم أعلى.'])}''')
add('working-capital-cycle','finance','🔄','دورة رأس المال العامل (CCC)','أيام المخزون والتحصيل والسداد ودورة تحويل النقد.',
 [F('inv','متوسط المخزون','n',300000),F('cogs','تكلفة المبيعات السنوية','n',2400000),F('ar','متوسط الذمم المدينة','n',250000),F('rev','الإيرادات السنوية','n',3200000),F('ap','متوسط الذمم الدائنة','n',200000)],
 r'''function compute(v){const dio=v.inv/v.cogs*365,dso=v.ar/v.rev*365,dpo=v.ap/v.cogs*365,ccc=dio+dso-dpo;return kpis([kpi('أيام المخزون',f(dio,0)),kpi('أيام التحصيل',f(dso,0)),kpi('أيام السداد',f(dpo,0)),kpi('دورة النقد',f(ccc,0)+' يوم',ccc>60?'bad':'good'),kpi('نقد محبوس',f(ccc*v.rev/365))])+rec(['خفّض يومًا من الدورة يحرر '+f(v.rev/365)+' نقدًا.','تفاوض على شروط الموردين وسرّع التحصيل.'])}''')
# ---- التسويق
add('marketing-mix-modeler','marketing','🎛️','محاكي مزيج التسويق والعائد','قارن سيناريوهات توزيع الميزانية بين القنوات حسب عائد كل قناة وتشبّعها.',
 [F('b','الميزانية','n',20000),F('c','القنوات (اسم | ROAS عند 1000 | معامل تشبع 0-1)','textarea','سناب | 4 | 0.7\nجوجل | 3.5 | 0.8\nانستغرام | 3 | 0.6',r=4)],
 r'''function compute(v){const L=lines(v.c).map(r=>({n:r[0],r:num(r[1]),s:num(r[2])}));const w=L.map(x=>x.r*(1-x.s/2)),sw=w.reduce((a,b)=>a+b,0);const rows=L.map((x,i)=>{const m=v.b*w[i]/sw,rev=x.r*1000*Math.pow(m/1000,x.s);return[x.n,f(m),f(rev),f(rev/m,2)+'x']});const tot=rows.reduce((a,r)=>a+num(String(r[2]).replace(/,/g,'')),0);return tbl(['القناة','الميزانية','الإيراد المقدر','ROAS'],rows)+kpis([kpi('إجمالي الإيراد',f(tot),'good'),kpi('ROAS الكلي',f(tot/v.b,2)+'x')])+rec(['القنوات تتشبّع: العائد لا يتضاعف بتضاعف الإنفاق.','النموذج تقريبي، اضبطه ببياناتك.'])}''')
add('brand-health-scorecard','marketing','🏅','بطاقة صحة العلامة التجارية','تقييم الوعي والتفضيل والولاء والتوصية بدرجة واحدة.',
 [F('a','وعي بالعلامة % (من جمهورك)','n',35),F('c','نية الاعتبار %','n',20),F('p','تفضيل على المنافسين %','n',12),F('l','نسبة التكرار %','n',28),F('n','NPS','n',32)],
 r'''function compute(v){const s=v.a*0.2+v.c*0.2+v.p*0.2+v.l*0.2+(v.n+100)/2*0.2;return kpis([kpi('درجة الصحة',f(s,0)+'/100',s>=50?'good':'bad'),kpi('فجوة الوعي→الاعتبار',f(v.a-v.c,0)+' نقطة'),kpi('فجوة الاعتبار→التفضيل',f(v.c-v.p,0)+' نقطة')])+rec([v.a-v.c>20?'وعي مرتفع واعتبار ضعيف: عزز الرسالة والدليل.':'قمع الاعتبار متوازن.',v.l<25?'التكرار ضعيف: برنامج ولاء ورسائل ما بعد الشراء.':'تكرار جيد.'])}''')
# ---- التجارة الإلكترونية
add('inventory-reorder-point','ecom','📦','نقطة إعادة الطلب والمخزون الآمن','متى تطلب وكم تطلب؟ مع مخزون الأمان.',
 [F('d','متوسط المبيعات اليومية','n',20),F('l','مدة التوريد (يوم)','n',14),F('s','أقصى مبيعات يومية','n',30),F('lm','أقصى مدة توريد','n',20),F('o','تكلفة الطلب الواحد','n',300),F('h','تكلفة حفظ الوحدة سنويًا','n',4)],
 r'''function compute(v){const ss=v.s*v.lm-v.d*v.l,rop=v.d*v.l+ss,eoq=Math.sqrt(2*v.d*365*v.o/v.h);return kpis([kpi('مخزون الأمان',f(ss,0)),kpi('نقطة إعادة الطلب',f(rop,0),'good'),kpi('الكمية الاقتصادية EOQ',f(eoq,0))])+rec(['اطلب عندما يصل المخزون إلى '+f(rop,0)+' وحدة.','راجع المتوسطات كل شهر أو في المواسم.'])}''')
add('customer-acquisition-channels-roi','ecom','🧭','مقارنة قنوات اكتساب العملاء للمتجر','أي قناة تعطي أفضل ربح بعد الاكتساب والمرتجعات؟',
 [F('c','القنوات (اسم | إنفاق | طلبات | متوسط الطلب | هامش %)','textarea','سناب | 8000 | 120 | 210 | 35\nانستغرام | 6000 | 70 | 240 | 38\nبحث جوجل | 4000 | 90 | 190 | 33\nبريد/واتساب | 500 | 60 | 200 | 40',r=6)],
 r'''function compute(v){const R=lines(v.c).map(r=>{const sp=num(r[1]),o=num(r[2]),a=num(r[3]),m=num(r[4]),rev=o*a,pr=rev*m/100-sp;return[r[0],f(sp/o),f(rev/sp,2)+'x',f(pr),pr]}).sort((a,b)=>b[4]-a[4]);return tbl(['القناة','تكلفة الطلب','ROAS','الربح'],R.map(r=>r.slice(0,4)))+rec(['الأفضل ربحًا: '+R[0][0],'انقل جزءًا من ميزانية القناة الأقل ربحًا.'])}''')
# ---- الإدارة
add('project-risk-register','management','🚧','سجل مخاطر المشروع','رتب المخاطر باحتمال×أثر وحدد أولويات المعالجة.',
 [F('r','المخاطر (وصف | احتمال 1-5 | أثر 1-5)','textarea','تأخر المورد | 4 | 4\nتجاوز الميزانية | 3 | 5\nاستقالة عضو رئيسي | 2 | 4\nتغير النطاق | 4 | 3',r=6)],
 r'''function compute(v){const R=lines(v.r).map(r=>{const s=num(r[1])*num(r[2]);return[r[0],num(r[1]),num(r[2]),s,s>=15?'🔴 عالٍ':s>=8?'🟡 متوسط':'🟢 منخفض']}).sort((a,b)=>b[3]-a[3]);return tbl(['الخطر','الاحتمال','الأثر','الدرجة','المستوى'],R)+rec(['ضع خطة استجابة وصاحبًا لكل خطر أحمر.','راجع السجل أسبوعيًا.'])}''')
add('balanced-scorecard-builder','management','🎚️','منشئ بطاقة الأداء المتوازن','مؤشرات لكل منظور: مالي، عملاء، عمليات، تعلم ونمو.',
 [F('g','الهدف الاستراتيجي','text','أن نصبح الأول في خدمة العملاء بالمنطقة')],
 r'''function compute(v){return tbl(['المنظور','هدف مقترح','مؤشر','مستهدف'],[['المالي','نمو إيرادات مستدام','نمو الإيراد %','+15% سنويًا'],['العملاء','رضا وولاء أعلى','NPS / معدل التكرار','NPS > 50'],['العمليات','سرعة وجودة','زمن الاستجابة / نسبة الأخطاء','< 4 ساعات / < 1%'],['التعلم والنمو','فريق مؤهل','ساعات تدريب / الاحتفاظ بالموظفين','40 ساعة / 90%']])+rec(['اربط كل مؤشر بصاحب وإيقاع مراجعة.','لا تتجاوز 3-4 مؤشرات لكل منظور.'])+aiOut('ابنِ بطاقة أداء متوازن تفصيلية للهدف الاستراتيجي: '+v.g)}''')
# ---- الموارد البشرية
add('compensation-benchmark','hr','⚖️','أداة موازنة الرواتب والعدالة الداخلية','قارن راتب موظف بنطاق الوظيفة (Compa-ratio).',
 [F('s','الراتب الحالي','n',9000),F('min','حد أدنى للنطاق','n',7000),F('max','حد أعلى للنطاق','n',13000)],
 r'''function compute(v){const mid=(v.min+v.max)/2,cr=v.s/mid,pos=(v.s-v.min)/(v.max-v.min)*100;return kpis([kpi('منتصف النطاق',f(mid)),kpi('Compa-ratio',f(cr,2),cr<0.9?'bad':cr>1.1?'bad':'good'),kpi('موقع في النطاق',f(pos,0)+'%')])+rec([cr<0.9?'الراتب أقل من المتوسط: خطر فقد الموظف.':cr>1.1?'الراتب فوق المنتصف: راجع الأداء والعدالة.':'الراتب ضمن النطاق العادل.'])}''')
add('performance-calibration','hr','📐','معايرة تقييم الأداء','توزيع التقييمات مقابل التوزيع المرجعي لاكتشاف التساهل.',
 [F('a','ممتاز (عدد)','n',12),F('b','جيد جدًا','n',25),F('c','جيد','n',35),F('d','مقبول','n',8),F('e','ضعيف','n',2)],
 r'''function compute(v){const t=v.a+v.b+v.c+v.d+v.e,R=[['ممتاز',v.a,10],['جيد جدًا',v.b,25],['جيد',v.c,45],['مقبول',v.d,15],['ضعيف',v.e,5]];return tbl(['التقدير','العدد','فعلي %','مرجعي %','الفرق'],R.map(r=>[r[0],r[1],f(r[1]/t*100,0),r[2],f(r[1]/t*100-r[2],0)]))+rec([v.a/t>0.2?'تقييمات «ممتاز» مرتفعة: راجع التساهل بين المديرين.':'التوزيع قريب من المرجع.','المعايرة تتم بنقاش بين المديرين بأدلة.'])}''')
# ---- الموظف
add('learning-roi-planner','career','🎓','مخطط عائد الاستثمار في التعلم','هل تستحق الدورة؟ زيادة الدخل المتوقعة مقابل التكلفة والوقت.',
 [F('c','تكلفة الدورة','n',3000),F('h','ساعات الدراسة','n',60),F('v','قيمة ساعتك','n',40),F('u','زيادة دخل شهرية متوقعة','n',500)],
 r'''function compute(v){const tc=v.c+v.h*v.v,pb=tc/v.u;return kpis([kpi('التكلفة الكلية',f(tc)),kpi('استرداد (شهر)',f(pb,1),pb<=12?'good':'bad'),kpi('عائد سنتين',f(v.u*24-tc),'good')])+rec([pb>18?'العائد بطيء: ابحث عن دورة أقصر أو أنفع.':'استثمار جيد إن تحقق الدخل.','طبّق المهارة في مشروع حقيقي خلال شهر.'])}''')
add('career-decision-matrix','career','🧭','مقارنة فرص العمل بأوزانك','قارن وظيفتين أو أكثر بمعاييرك الشخصية.',
 [F('c','المعايير | الوزن','textarea','الراتب | 30\nالنمو | 25\nالتوازن | 25\nالاستقرار | 20',r=4),F('o','الفرص | الدرجات 1-10','textarea','شركة أ | 8,6,5,7\nشركة ب | 6,8,8,8',r=3)],
 r'''function compute(v){const W=lines(v.c).map(r=>num(r[1])),tw=W.reduce((a,b)=>a+b,0);const R=lines(v.o).map(r=>[r[0],String(r[1]).split(',').map(Number).reduce((a,x,i)=>a+x*(W[i]||0),0)/tw]).sort((a,b)=>b[1]-a[1]);return tbl(['الفرصة','الدرجة'],R.map(r=>[r[0],f(r[1],2)]))+rec(['الأعلى: '+R[0][0],'لا تهمل الإحساس: النتيجة أداة مساعدة لا بديل عن القرار.'])}''')
# ---- المبيعات / السوق
add('win-loss-analyzer','sales','🔍','محلل الصفقات الرابحة والخاسرة','أسباب الفوز والخسارة ومعدل الفوز حسب المصدر.',
 [F('d','الصفقات (مصدر | نتيجة ربح/خسارة | سبب)','textarea','إحالة | ربح | ثقة\nإعلان | خسارة | السعر\nإعلان | ربح | سرعة الرد\nمعرض | خسارة | منافس\nإحالة | ربح | ثقة\nإعلان | خسارة | السعر',r=7)],
 r'''function compute(v){const L=lines(v.d),src={},why={};L.forEach(r=>{const w=r[1]==='ربح';src[r[0]]=src[r[0]]||[0,0];src[r[0]][w?0:1]++;if(!w)why[r[2]]=(why[r[2]]||0)+1});const t=L.filter(r=>r[1]==='ربح').length;return kpis([kpi('معدل الفوز',f(t/L.length*100,0)+'%')])+tbl(['المصدر','ربح','خسارة','معدل الفوز'],Object.entries(src).map(([k,x])=>[k,x[0],x[1],f(x[0]/(x[0]+x[1])*100,0)+'%']))+tbl(['سبب الخسارة','التكرار'],Object.entries(why).sort((a,b)=>b[1]-a[1]))+rec(['ضاعف الاستثمار في المصدر الأعلى فوزًا.','عالج السبب الأول للخسارة أولًا.'])}''')
add('competitive-price-position','market','📏','خريطة تموضع الأسعار','موقعك السعري بين المنافسين وفجوات السوق.',
 [F('p','منتجات (اسم | سعر | جودة 1-10)','textarea','أنت | 150 | 7\nمنافس أ | 100 | 5\nمنافس ب | 220 | 9\nمنافس ج | 140 | 6',r=5)],
 r'''function compute(v){const R=lines(v.p).map(r=>({n:r[0],p:num(r[1]),q:num(r[2])}));const me=R[0],o=R.slice(1);const val=R.map(x=>[x.n,f(x.p),x.q,f(x.q/x.p*100,2)]).sort((a,b)=>num(b[3])-num(a[3]));const cheaperBetter=o.filter(x=>x.p<=me.p&&x.q>=me.q);return tbl(['العلامة','السعر','الجودة','قيمة (جودة/سعر×100)'],val)+rec([cheaperBetter.length?'منافسون أرخص وأفضل منك: '+cheaperBetter.map(x=>x.n).join('، ')+' — غيّر التموضع أو حسّن الجودة.':'لا منافس أرخص وأفضل منك في هذه المقارنة.','ابحث عن فراغ سعري بجودة مناسبة بين المنافسين.'])}''')
